          if (value === 'done' || value === 'snoozed') state.statuses[plant.id] = value;
        }
      }
      if (Array.isArray(saved.week) && saved.week.length === 7) {
        state.week = saved.week.map((n) => (Number.isFinite(n) && n >= 0 ? n : 0));
      }
      if (Array.isArray(saved.log)) {
        state.log = saved.log
          .filter((entry) => entry && PLANT_BY_ID.has(entry.id) && typeof entry.time === 'string')
          .slice(0, 24)
          .map((entry) => ({
            id: entry.id,
            label: typeof entry.label === 'string' ? entry.label : CARE[entry.id].done,
            time: entry.time
          }));
      }
      if (PLANT_BY_ID.has(saved.selectedId)) state.selectedId = saved.selectedId;
      return state;
    } catch (err) {
      return freshState();
    }
  }

  let state = loadState();
  const undoStack = [];
  let sheetOpen = false;
  let lastTrigger = null;
  let wasAllDone = false;

  function save() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(state));
    } catch (err) {
      /* private mode / quota — the day still works in memory */
    }
  }

  function snapshot() {
    return JSON.parse(JSON.stringify(state));
  }

  function statusOf(id) {
    return state.statuses[id];
  }

  function pendingPlants() {
    return PLANTS
      .filter((plant) => !statusOf(plant.id))
      .sort((a, b) => b.urgency - a.urgency);
  }

  function allDone() {
    return PLANTS.every((plant) => statusOf(plant.id) === 'done');
  }

  /* ---------------------------------------------------------
     Little helpers
     --------------------------------------------------------- */

  const esc = (value) => String(value).replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[ch]));

  const numWord = (n) => ['zero', 'one', 'two', 'three', 'four'][n] || String(n);
  const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

  function timeNow() {
    const d = new Date();
    const h = d.getHours() % 12 || 12;
    const m = String(d.getMinutes()).padStart(2, '0');
    const suffix = d.getHours() < 12 ? 'am' : 'pm';
    return `${h}:${m}${suffix}`;
  }

  function splitEvent(str) {
    const parts = String(str).split(' · ');
    return { date: parts.shift() || '', text: parts.join(' · ') };
  }

  function lightLevel(light) {
    const value = light.toLowerCase();
    if (value.includes('bright')) return 3;
    if (value.includes('medium')) return 2;
    return 1;
  }

  function plantArt(id) {
    return `<svg viewBox="0 0 64 64" aria-hidden="true" focusable="false">${ART[id] || ''}</svg>`;
  }

  function dueTag(plant) {
    const due = plant.due.toLowerCase();
    const cls = due.includes('overdue') ? ' due--late' : due === 'today' ? ' due--today' : '';
    return `<span class="due${cls}">${esc(plant.due)}</span>`;
  }

  function eventGlyph(text) {
    const value = text.toLowerCase();
    if (value.includes('water')) return ICONS.drop;
    if (value.includes('mist')) return ICONS.mist;
    if (value.includes('rotat')) return ICONS.rotate;
    if (value.includes('frond') || value.includes('pad') || value.includes('leaf')) return ICONS.leaf;
    if (value.includes('brown') || value.includes('edge')) return ICONS.alert;
    if (value.includes('wip') || value.includes('clean')) return ICONS.sparkle;
    return ICONS.dot;
  }

  /* ---------------------------------------------------------
     Render: greeting
     --------------------------------------------------------- */

  function renderGreeting() {
    const pending = pendingPlants();
    const doneCount = PLANTS.filter((p) => statusOf(p.id) === 'done').length;
    const resting = PLANTS.filter((p) => statusOf(p.id) === 'snoozed').length;
    const finished = allDone();

    if (finished) {
      els.lede.textContent = 'Nothing left but the growing. The afternoon is yours.';
    } else if (pending.length === 0) {
      els.lede.textContent = 'The house is resting. So can you.';
    } else {
      els.lede.textContent = `${cap(numWord(pending.length))} small ${pending.length === 1 ? 'thing' : 'things'} to tend. The plants are patient, mostly.`;
    }

    const pips = PLANTS.map((plant) => {
      const status = statusOf(plant.id);
      const cls = status === 'done' ? ' pip--done' : status === 'snoozed' ? ' pip--resting' : '';
      return `<span class="pip${cls}"></span>`;
    }).join('');

    els.progress.innerHTML =
      `<div class="pips" aria-hidden="true">${pips}</div>` +
      `<p class="progress-text">${doneCount} of ${PLANTS.length} tended${resting ? ` · ${resting} resting` : ''}</p>`;

    if (finished) {
      els.mossLine.textContent = 'Four friends, all tended. I’m going to sit in the sun about it.';
      return;
    }
    if (pending.length === 0) {
      els.mossLine.textContent = 'Everyone’s resting. Care includes leaving things alone.';
      return;
    }

    const first = pending[0];
    if (first.due.toLowerCase().includes('overdue')) {
      els.mossLine.textContent = `Start with ${first.name} — ${first.due.toLowerCase()}. The leaves have noticed.`;
    } else if (first.due.toLowerCase() === 'today') {
      els.mossLine.textContent = `${first.name} is up first. A small thing, done gently.`;
    } else {
      els.mossLine.textContent = `${first.name} can wait until tomorrow. But why wait?`;
    }
  }

  /* ---------------------------------------------------------
     Render: queue
     --------------------------------------------------------- */

  function taskHTML(plant, index) {
    const overdue = plant.due.toLowerCase().includes('overdue');
    const selected = state.selectedId === plant.id;
    const care = CARE[plant.id];
    return `
      <li class="task${overdue ? ' is-overdue' : ''}${selected ? ' is-selected' : ''}" data-id="${plant.id}" style="--i:${index}">
        <button class="task-open" type="button" data-open="${plant.id}" aria-controls="detail">
          <span class="task-tile tile-${plant.id}" aria-hidden="true">${plantArt(plant.id)}</span>
          <span class="task-copy">
            <span class="task-line">
              <span class="task-name">${esc(plant.name)}</span>
              ${dueTag(plant)}
            </span>
            <span class="task-meta">${esc(plant.species)}<span class="dot">·</span>${esc(plant.location)}</span>
            <span class="sr-only">Open plant details for ${esc(plant.name)}</span>
          </span>
          <span class="task-chevron" aria-hidden="true">${ICONS.chevron}</span>
        </button>
        <div class="task-actions">
          <button class="btn btn--done" type="button" data-done="${plant.id}" aria-label="${care.done} — ${esc(plant.name)}">
            ${ICONS.check}<span>${care.done}</span>
          </button>
          <button class="btn btn--snooze" type="button" data-snooze="${plant.id}" aria-label="Snooze ${esc(plant.name)} until tomorrow">
            ${ICONS.moon}<span>Snooze</span>
          </button>
        </div>
      </li>`;
  }

  function miniRow(plant, note, actionAttr, actionLabel, actionText) {
    return `
      <li class="mini-row">
        <span class="mini-tile tile-${plant.id}" aria-hidden="true">${plantArt(plant.id)}</span>
        <span class="mini-copy">
          <button class="mini-open" type="button" data-open="${plant.id}">${esc(plant.name)}</button>
          <span class="mini-note">${note}</span>
        </span>
        <button class="mini-btn" type="button" ${actionAttr}="${plant.id}" aria-label="${actionLabel}">${actionText}</button>
      </li>`;
  }

  function allowedClasses() {
    /* nothing — helper kept out of the way */
  }

  function renderQueue() {
    const pending = pendingPlants();
    const finished = allDone();
    const resting = PLANTS.filter((p) => statusOf(p.id) === 'snoozed');
    const done = PLANTS.filter((p) => statusOf(p.id) === 'done');

    els.queueList.innerHTML = pending.map((plant, i) => taskHTML(plant, i)).join('');
    els.queueList.hidden = pending.length === 0;

    els.queueCount.textContent = finished ? 'all tended' : pending.length === 0 ? 'resting' : `${pending.length} left`;

    if (finished) {
      els.nudge.textContent = 'Round complete. Not a single leaf owes you anything.';
    } else if (pending.length === 0) {
      els.nudge.textContent = 'Everything’s resting. Nothing else is due today.';
    } else {
      const first = pending[0];
      els.nudge.textContent = first.due.toLowerCase().includes('overdue')
        ? `Start with ${first.name} — ${first.due.toLowerCase()}.`
        : `First up: ${first.name} — ${first.due.toLowerCase()}.`;
    }

    /* Quiet state */
    if (!finished && pending.length === 0) {
      const restCount = resting.length;
      els.quiet.hidden = false;
      els.quiet.innerHTML = `
        <div class="alldone alldone--quiet">
          <div class="quiet-seal" aria-hidden="true">${QUIET_SEAL}</div>
          <p class="alldone-kicker">Nothing due</p>
          <h3 id="quiet-title">Everyone’s<br><em>resting.</em></h3>
          <p class="alldone-copy">${restCount
            ? `${cap(numWord(restCount))} ${restCount === 1 ? 'plant is' : 'plants are'} snoozed until tomorrow. The rest of the house is quiet.`
            : 'The round is clear. Take the afternoon.'}</p>
          <div class="alldone-actions">
            ${restCount ? '<button class="btn btn--done" type="button" data-wake-all>Wake everyone</button>' : ''}
            <button class="btn btn--snooze" type="button" data-reset>Start a fresh day</button>
          </div>
        </div>`;
    } else {
      els.quiet.hidden = true;
      els.quiet.innerHTML = '';
    }

    /* All done */
    if (finished) {
      els.alldone.hidden = false;
      els.alldone.innerHTML = `
        <div class="alldone">
          <div class="alldone-seal">${SEAL}</div>
          <p class="alldone-kicker">Round complete</p>
          <h3 id="alldone-title">All tended.<br><em>Nothing owed.</em></h3>
          <p class="alldone-copy">Four small kindnesses, witnessed by the window. The light will take it from here.</p>
          <p class="alldone-next">Next nudge · tomorrow morning</p>
          <div class="alldone-actions">
            <button class="btn btn--snooze" type="button" data-undo-last ${state.log.length ? '' : 'hidden'}>Undo last</button>
            <button class="btn btn--done" type="button" data-reset>Start a fresh day</button>
          </div>
        </div>`;
    } else {
      els.alldone.hidden = true;
      els.alldone.innerHTML = '';
    }

    /* Resting list */
    if (resting.length) {
      els.resting.hidden = false;
      els.resting.innerHTML = `
        <p class="sub-label">Resting until tomorrow</p>
        <ul class="mini-list">
          ${resting.map((plant) => miniRow(
            plant,
            'Snoozed · back tomorrow',
            'data-wake',
            `Wake ${plant.name}’s task`,
            'Wake'
          )).join('')}
        </ul>`;
    } else {
      els.resting.hidden = true;
      els.resting.innerHTML = '';
    }

    /* Tended list */
    if (done.length) {
      els.tended.hidden = false;
      els.tended.innerHTML = `
        <p class="sub-label">Tended today</p>
        <ul class="mini-list">
          ${done.map((plant) => {
            const entry = state.log.find((item) => item.id === plant.id);
            const note = entry ? `${entry.label} · ${entry.time}` : CARE[plant.id].done;
            return miniRow(
              plant,
              note,
              'data-restore',
              `Undo ${plant.name}’s care`,
              'Undo'
            );
          }).join('')}
        </ul>`;
    } else {
      els.tended.hidden = true;
      els.tended.innerHTML = '';
    }

    els.queueHint.hidden = false;
    void allowedClasses;
  }

  /* ---------------------------------------------------------
     Render: weekly rhythm
     --------------------------------------------------------- */

  function renderRhythm() {
    const week = state.week;
    const max = Math.max(...week, 1);
    const total = week.reduce((sum, n) => sum + n, 0);

    els.rhythmSum.textContent = `${total} small acts this week`;

    els.rhythmBars.innerHTML = week.map((value, i) => {
      const height = Math.max(6, Math.round((value / max) * 100));
      const today = i === TODAY_INDEX;
      return `
        <li class="bar-item${today ? ' is-today' : ''}">
          <span class="bar-track" aria-hidden="true"><span class="bar" style="--h:${height}%"></span></span>
          <span class="bar-day" aria-hidden="true">${DAY_LETTERS[i]}</span>
          <span class="sr-only">${DAY_NAMES[i]}: ${value} ${value === 1 ? 'care moment' : 'care moments'}${today ? ', today' : ''}</span>
        </li>`;
    }).join('');

    const best = week.indexOf(Math.max(...week));
    els.rhythmFoot.textContent = best === TODAY_INDEX
      ? 'Thursday is carrying the week. No pressure.'
      : `${DAY_NAMES[best]} is carrying the week. Thursday can catch up.`;
  }

  /* ---------------------------------------------------------
     Render: detail
     --------------------------------------------------------- */

  function renderDetail() {
    const plant = PLANT_BY_ID.get(state.selectedId) || PLANTS[0];
    const status = statusOf(plant.id);
    const care = CARE[plant.id];
    const lastWater = plant.history
      .map(splitEvent)
      .find((event) => event.text.toLowerCase().includes('water'));

    let actions;
    if (status === 'done') {
      const entry = state.log.find((item) => item.id === plant.id);
      actions = `
        <div class="detail-state">
          <span class="state-check" aria-hidden="true">${ICONS.check}</span>
          <p>
            <strong>Tended today</strong>
            <span>${entry ? `${esc(entry.label)} · ${esc(entry.time)}` : 'Done for today'}</span>
          </p>
          <button class="mini-btn" type="button" data-restore="${plant.id}" aria-label="Undo ${esc(plant.name)}’s care">Undo</button>
        </div>`;
    } else if (status === 'snoozed') {
      actions = `
        <div class="detail-state">
          <span class="state-check state-check--rest" aria-hidden="true">${ICONS.moon}</span>
          <p>
            <strong>Resting until tomorrow</strong>
            <span>Snoozed for one day</span>
          </p>
          <button class="mini-btn" type="button" data-wake="${plant.id}" aria-label="Wake ${esc(plant.name)}’s task">Wake</button>
        </div>`;
    } else {
      actions = `
        <div class="detail-actions">
          <button class="btn btn--done" type="button" data-done="${plant.id}" aria-label="${care.done} — ${esc(plant.name)}">
            ${ICONS.check}<span>${care.done}</span>
          </button>
          <button class="btn btn--snooze" type="button" data-snooze="${plant.id}" aria-label="Snooze ${esc(plant.name)} until tomorrow">
            ${ICONS.moon}<span>Snooze</span>
          </button>
        </div>`;
    }

    els.detail.innerHTML = `
      ${WATERMARK}
      <span class="sheet-handle" aria-hidden="true"></span>
      <div class="detail-top">
        <p class="detail-kicker">In focus</p>
        <button class="detail-close" type="button" data-close-detail aria-label="Close plant details">${ICONS.close}</button>
      </div>
      <div class="detail-hero">
        <div class="detail-art tile-${plant.id}" aria-hidden="true">${plantArt(plant.id)}</div>
        <div class="detail-id">
          <h2 id="detail-name">${esc(plant.name)}</h2>
          <p class="detail-species">${esc(plant.species)}</p>
          <p class="detail-loc">${ICONS.pin}<span>${esc(plant.location)}</span></p>
        </div>
      </div>
      <div class="detail-ask">
        <span class="detail-ask-label">Today’s ask</span>
        <strong>${esc(care.verb)}</strong>
        ${dueTag(plant)}
      </div>
      <div class="detail-facts">
        <div class="fact">
          <span class="fact-label">Light</span>
          <span class="fact-value">${esc(plant.light)}</span>
          <span class="meter" aria-hidden="true">${[1, 2, 3].map((n) => `<span class="meter-bar${n <= lightLevel(plant.light) ? ' is-on' : ''}"></span>`).join('')}</span>
        </div>
        <div class="fact">
          <span class="fact-label">Water</span>
          <span class="fact-value">${lastWater ? esc(lastWater.date) : '—'}</span>
          <span class="fact-note">${lastWater ? 'Last watered' : 'No watering logged'}</span>
        </div>
      </div>
      ${actions}
      <p class="detail-whisper"><span class="whisper-label">Moss, quietly</span>“${esc(WHISPERS[plant.id])}”</p>
      <h3 class="detail-h3">Observations &amp; care <span>newest first</span></h3>
      <ol class="timeline">
        ${plant.history.map((entry) => {
          const event = splitEvent(entry);
          return `
            <li>
              <span class="timeline-icon" aria-hidden="true">${eventGlyph(event.text)}</span>
              <div>
                <time>${esc(event.date)}</time>
                <span class="timeline-text">${esc(event.text)}</span>
              </div>
            </li>`;
        }).join('')}
      </ol>`;
  }

  /* ---------------------------------------------------------
     Render: everything
     --------------------------------------------------------- */

  function render() {
    const finished = allDone();
    document.body.classList.toggle('all-done', finished);
    renderGreeting();
    renderQueue();
    renderRhythm();
    renderDetail();
    if (finished && !wasAllDone) celebrate();
    wasAllDone = finished;
  }

  /* ---------------------------------------------------------
     Detail sheet behaviour
     --------------------------------------------------------- */

  function openDetail(id, trigger) {
    if (!PLANT_BY_ID.has(id)) return;
    state.selectedId = id;
    save();
    renderDetail();
    document.querySelectorAll('.task').forEach((li) => {
      li.classList.toggle('is-selected', li.dataset.id === id);
    });

    if (mqMobile.matches) {
      lastTrigger = trigger || document.activeElement;
      openSheet();
    } else {
      const plant = PLANT_BY_ID.get(id);
      els.detailLive.textContent = `${plant.name}, ${plant.species}. Plant details shown.`;
    }
  }

  function openSheet() {
    if (sheetOpen) return;
    sheetOpen = true;
    els.detail.inert = false;
    els.detail.removeAttribute('aria-hidden');
    els.detail.setAttribute('aria-modal', 'true');
    els.detail.classList.add('is-open');
    document.body.classList.add('sheet-open');
    window.requestAnimationFrame(() => {
      const close = els.detail.querySelector('.detail-close');
      if (close) close.focus({ preventScroll: true });
    });
  }

  function closeSheet(restoreFocus = true) {
    if (!sheetOpen) return;
    sheetOpen = false;
    els.detail.classList.remove('is-open');
    document.body.classList.remove('sheet-open');
    els.detail.setAttribute('aria-hidden', 'true');
    els.detail.removeAttribute('aria-modal');
    els.detail.inert = true;
    if (restoreFocus && lastTrigger && document.contains(lastTrigger)) {
      lastTrigger.focus({ preventScroll: true });
    }
  }

  function syncLayout() {
    if (mqMobile.matches) {
      els.detail.setAttribute('role', 'dialog');
      if (!sheetOpen) {
        els.detail.setAttribute('aria-hidden', 'true');
        els.detail.removeAttribute('aria-modal');
        els.detail.inert = true;
        els.detail.classList.remove('is-open');
        document.body.classList.remove('sheet-open');
      }
    } else {
      if (els.detail.contains(document.activeElement)) {
        const row = document.querySelector(`.task-open[data-open="${state.selectedId}"]`);
        if (row) row.focus({ preventScroll: true });
      }
      sheetOpen = false;
      document.body.classList.remove('sheet-open');
      els.detail.classList.remove('is-open');
      els.detail.inert = false;
      els.detail.removeAttribute('role');
      els.detail.removeAttribute('aria-hidden');
      els.detail.removeAttribute('aria-modal');
    }
  }

  function trapFocus(event) {
    const focusables = Array.from(
      els.detail.querySelectorAll('button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])')
    ).filter((el) => el.offsetParent !== null);
    if (!focusables.length) return;
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    const active = document.activeElement;
    if (event.shiftKey) {
      if (active === first || !els.detail.contains(active)) {
        event.preventDefault();
        last.focus();
      }
    } else if (active === last || !els.detail.contains(active)) {
      event.preventDefault();
      first.focus();
    }
  }

  /* ---------------------------------------------------------
     Care actions + undo
     --------------------------------------------------------- */

  function pushUndo(id) {
    undoStack.push({ snap: snapshot(), id });
    if (undoStack.length > 24) undoStack.shift();
  }

  function perform(id, kind, trigger) {
    const plant = PLANT_BY_ID.get(id);
    if (!plant || statusOf(id)) return;

    pushUndo(id);

    if (kind === 'done') {
      state.statuses[id] = 'done';
      state.week[TODAY_INDEX] = (state.week[TODAY_INDEX] || 0) + 1;
      state.log.unshift({ id, label: CARE[id].done, time: timeNow() });
      state.log = state.log.slice(0, 24);
    } else {
      state.statuses[id] = 'snoozed';
    }

    save();
    if (sheetOpen) closeSheet(false);
    if (kind === 'done' && trigger) splash(trigger);
    render();
    showToast(
      kind === 'done'
        ? `${plant.name} ${CARE[id].past}.`
        : `${plant.name} is resting until tomorrow.`,
      undoLast,
      kind === 'done' ? 'drop' : 'moon'
    );
    focusAfterChange(null);
  }

  function restorePlant(id) {
    const plant = PLANT_BY_ID.get(id);
    const status = statusOf(id);
    if (!plant || !status) return;

    if (status === 'done') {
      state.week[TODAY_INDEX] = Math.max(0, (state.week[TODAY_INDEX] || 0) - 1);
      state.log = state.log.filter((entry) => entry.id !== id);
    }
    delete state.statuses[id];
    if (state.selectedId === id) { /* keep it in focus */ }
    save();
    render();
    showToast(`${plant.name} is back in the queue.`, null, 'leaf');
    focusAfterChange(id);
  }

  function wakeAll() {
    const sleeping = PLANTS.filter((p) => statusOf(p.id) === 'snoozed');
    if (!sleeping.length) return;
    pushUndo(sleeping[0].id);
    sleeping.forEach((plant) => { delete state.statuses[plant.id]; });
    save();
    render();
    showToast('Everyone’s back on the list. No rush.', undoLast, 'leaf');
    focusAfterChange(sleeping[0].id);
  }

  function resetDay() {
    undoStack.push({ snap: snapshot(), id: null });
    const selected = state.selectedId;
    state = freshState();
    state.selectedId = selected;
    save();
    render();
    showToast('A fresh day. Everything’s due again.', undoLast, 'leaf');
    focusAfterChange(null);
  }

  function undoLast() {
    const item = undoStack.pop();
    if (!item) {
      showToast('Nothing to undo just yet.', null, 'leaf');
      return;
    }
    state = item.snap;
    save();
    render();
    showToast('Put back. No harm done.', null, 'leaf');
    focusAfterChange(item.id);
  }

  function focusAfterChange(id) {
    window.requestAnimationFrame(() => {
      if (sheetOpen) {
        const inside = els.detail.querySelector('.detail-actions .btn, .detail-state .mini-btn, .detail-close');
        if (inside) {
          inside.focus({ preventScroll: true });
          return;
        }
      }

      if (id) {
        const restored = document.querySelector(`.task-open[data-open="${id}"]`);
        if (restored) {
          restored.focus({ preventScroll: true });
          return;
        }
      }

      const next = document.querySelector('.task-open');
      if (next) {
        next.focus({ preventScroll: true });
        return;
      }

      const end = document.querySelector('#alldone h3, #quiet h3');
      if (end) {
        end.tabIndex = -1;
        end.focus({ preventScroll: true });
      }
    });
  }

  /* ---------------------------------------------------------
     Toast
     --------------------------------------------------------- */

  let toastTimer = null;
  let toastVisible = false;
  let toastAction = null;

  function showToast(message, action, kind) {
    clearTimeout(toastTimer);
    els.toastMsg.textContent = message;
    els.toastIcon.innerHTML = kind === 'moon' ? ICONS.moon : kind === 'drop' ? ICONS.drop : ICONS.leaf;
    els.toastUndo.hidden = !action;
    toastAction = action || null;
    toastVisible = true;
    els.toast.classList.add('is-visible');
    startToastTimer();
  }

  function startToastTimer() {
    clearTimeout(toastTimer);
    if (!toastVisible) return;
    toastTimer = setTimeout(hideToast, 9000);
  }

  function pauseToast() {
    clearTimeout(toastTimer);
  }

  function hideToast() {
    clearTimeout(toastTimer);
    toastVisible = false;
    toastAction = null;
    els.toast.classList.remove('is-visible');
  }

  /* ---------------------------------------------------------
     Moments of delight
     --------------------------------------------------------- */

  function splash(trigger) {
    if (reduceMotion.matches) return;
    const rect = trigger.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    for (let i = 0; i < 5; i += 1) {
      const drop = document.createElement('span');
      drop.className = 'splash';
      drop.style.left = `${cx}px`;
      drop.style.top = `${cy}px`;
      drop.style.setProperty('--dx', `${(Math.random() * 2 - 1) * 46}px`);
      drop.style.setProperty('--dy', `${-28 - Math.random() * 34}px`);
      drop.style.setProperty('--delay', `${i * 35}ms`);
      document.body.appendChild(drop);
      setTimeout(() => drop.remove(), 1100);
    }
  }

  function celebrate() {
    if (reduceMotion.matches) return;
    const host = document.querySelector('#alldone .alldone');
    if (!host) return;
    const colors = ['#8FA77A', '#B98A63', '#E0C075', '#6E8B5A'];
    for (let i = 0; i < 9; i += 1) {
      const leaf = document.createElement('span');
      leaf.className = 'leaf-fall';
      leaf.style.setProperty('--x', `${6 + Math.random() * 88}%`);
      leaf.style.setProperty('--delay', `${Math.random() * 1.1}s`);
      leaf.style.setProperty('--dur', `${2.3 + Math.random() * 1.5}s`);
      leaf.style.setProperty('--drift', `${(Math.random() * 2 - 1) * 46}px`);
      leaf.style.setProperty('--spin', `${(Math.random() * 2 - 1) * 240}deg`);
      leaf.style.setProperty('--leaf', colors[i % colors.length]);
      host.appendChild(leaf);
      setTimeout(() => leaf.remove(), 5000);
    }
  }

  /* ---------------------------------------------------------
     Events
     --------------------------------------------------------- */

  document.addEventListener('click', (event) => {
    const open = event.target.closest('[data-open]');
    if (open) {
      openDetail(open.dataset.open, open);
      return;
    }

    const done = event.target.closest('[data-done]');
    if (done) {
      perform(done.dataset.done, 'done', done);
      return;
    }

    const snooze = event.target.closest('[data-snooze]');
    if (snooze) {
      perform(snooze.dataset.snooze, 'snoozed', snooze);
      return;
    }

    const wake = event.target.closest('[data-wake]');
    if (wake) {
      const id = wake.dataset.wake;
      const plant = PLANT_BY_ID.get(id);
      if (plant && statusOf(id) === 'snoozed') {
        delete state.statuses[id];
        save();
        render();
        showToast(`${plant.name} is back in today’s queue.`, null, 'leaf');
        focusAfterChange(id);
      }
      return;
    }

    const restore = event.target.closest('[data-restore]');
    if (restore) {
      restorePlant(restore.dataset.restore);
      return;
    }

    if (event.target.closest('[data-wake-all]')) {
      wakeAll();
      return;
    }

    if (event.target.closest('[data-undo-last]')) {
      undoLast();
      return;
    }

    if (event.target.closest('[data-reset]')) {
      resetDay();
      return;
    }

    if (event.target.closest('[data-close-detail]')) {
      closeSheet();
      return;
    }

    if (event.target === els.backdrop) {
      closeSheet();
    }
  });

  /* Toast buttons */
  els.toastUndo.addEventListener('click', () => {
    const action = toastAction;
    hideToast();
    if (action) action();
  });

  els.toastClose.addEventListener('click', () => {
    hideToast();
  });

  els.toast.addEventListener('mouseenter', pauseToast);
  els.toast.addEventListener('mouseleave', () => {
    if (toastVisible) startToastTimer();
  });
  els.toast.addEventListener('focusin', pauseToast);
  els.toast.addEventListener('focusout', (event) => {
    if (!els.toast.contains(event.relatedTarget) && toastVisible) startToastTimer();
  });

  /* Keyboard */
  document.addEventListener('keydown', (event) => {
    const key = event.key.toLowerCase();

    if ((event.metaKey || event.ctrlKey) && !event.altKey && key === 'z') {
      if (undoStack.length) {
        event.preventDefault();
        undoLast();
      }
      return;
    }

    if (event.key === 'Escape') {
      if (sheetOpen) {
        event.preventDefault();
        closeSheet();
        return;
      }
      if (toastVisible) hideToast();
      return;
    }

    if (sheetOpen && event.key === 'Tab') trapFocus(event);
  });

  if (typeof mqMobile.addEventListener === 'function') {
    mqMobile.addEventListener('change', syncLayout);
  } else if (typeof mqMobile.addListener === 'function') {
    mqMobile.addListener(syncLayout);
  }

  /* ---------------------------------------------------------
     Go
     --------------------------------------------------------- */

  syncLayout();
  render();
})();
